using namespace std;

class TicTacToe
{
	private:
		char scr[3][3];
	public:
		TicTacToe();
		void makeMove();
		void printBoard();
		int validMove();
		int gameStatus();
		void startGame();
};

int TicTacToe::validMove()
{
	int move, move1,player = 1, i;
	char mark = 'X';
	do
	{
		player = (player%2) ? 1 : 2;
		printBoard();
		mark=(player == 1) ? 'X' : 'O';
		cout << "Player " << mark << " turn: ";
		cin >> move >> move1;
		mark=(player == 1) ? 'X' : 'O';
		if(move == 0 &&move1 == 0&& scr[0][0] == ' ')
		{
			scr[0][0] = mark;
		}

		else if(move == 0 &&move1 == 1 && scr[0][1] == ' ')
		{
			scr[0][1] = mark;
		}
		else if(move == 0 &&move1 == 2 && scr[0][2] == ' ')
		{
			scr[0][2] = mark;
		}
		else if(move == 1&&move1 == 0 && scr[1][0] == ' ')
		{
			scr[1][0] = mark;
		}
		else if(move == 1&&move1 == 1 && scr[1][1] == ' ')
		{
			scr[1][1] = mark;
		}
		else if(move == 1 &&move1 == 2&& scr[1][2] == ' ')
		{
			scr[1][2] = mark;
		}

		else if(move == 2 &&move1 == 0 && scr[2][0] == ' ')
		{
			scr[2][0] = mark;
		}
		else if(move == 2 &&move1 == 1 && scr[2][1] == ' ')
		{
			scr[2][1] = mark;
		}
		else if(move == 2 &&move1 == 2 && scr[2][2] == ' ')
		{
			scr[2][2] = mark;
		}
		else
        {
            cout<<"Invalid move ";

            player--;
            cin.ignore();
            cin.get();
        }
	    i=gameStatus();

		player++;
    }while(i==-1);
    printBoard();
    if(i==1){
    	--player;
        cout<<"\n==>\aPlayer "<<mark<<" win " << endl;
        for(int sc = 0; sc < 3; sc++)
		{
			for(int ar = 0; ar < 3; ar++)
			{
				scr[sc][ar] = ' ';
			}
		}
	}

	else
	{
		cout<<"\n==>\aGame Draw" << endl;
		for(int sc = 0; sc < 3; sc++)
		{
			for(int ar = 0; ar < 3; ar++)
			{
				scr[sc][ar] = ' ';
			}
		}
	}
}

TicTacToe::TicTacToe()
{
	for(int sc = 0; sc < 3; sc++)
	{
		for(int ar = 0; ar < 3; ar++)
		{
			scr[sc][ar] = ' ';
		}
	}
}
int TicTacToe::gameStatus()
{
	if (scr[0][0] == scr[0][1] && scr[0][1] == scr[0][2] && scr[0][0] != ' ')

        return 1;
    else if (scr[1][0] == scr[1][1] && scr[1][1] == scr[1][2] && scr[1][0] != ' ')

        return 1;
    else if (scr[2][0] == scr[2][1] && scr[2][1] == scr[2][2] && scr[2][0] != ' ')

        return 1;

    else if (scr[0][0] == scr[1][0] && scr[1][0] == scr[2][0] && scr[0][0] != ' ')

        return 1;
    else if (scr[0][1] == scr[1][1] && scr[1][1] == scr[2][1] && scr[0][1] != ' ')

        return 1;
    else if (scr[0][2] == scr[1][2] && scr[1][2] == scr[2][2] && scr[0][2] != ' ')

        return 1;
    else if (scr[0][0] == scr[1][1] && scr[1][1] == scr[2][2] && scr[0][0] != ' ')

        return 1;
    else if (scr[0][2] == scr[1][1] && scr[1][1] == scr[2][0] && scr[0][2] != ' ')

        return 1;
    else if (scr[0][0] != ' ' && scr[0][1] != ' ' && scr[0][2] != ' '
                    && scr[1][0] != ' ' && scr[1][1] != ' ' && scr[1][2] != ' '
                  && scr[2][0] != ' ' && scr[2][1] != ' ' && scr[2][2] != ' ')

        return 0;
    else
        return -1;
}
void TicTacToe::makeMove()
{
	validMove();
}

void TicTacToe::startGame()
{
	makeMove();
}
void TicTacToe::printBoard()
{
//	system("cls || clear");
	cout << " 0\t1\t2" << endl << endl;
	cout << "0     :     :   " << endl;
	cout << "   "<< scr[0][0] << "  :  "<< ""<< scr[0][1] << "  :" << "  "<< scr[0][2] << endl;
